// Ported from Akantu (EPFL/LSMS): bitwise checks of src/common/aka_random_generator.hh
// semantics against oracle fixtures generated by oracle/probes/random/dump_random.cc
// (GCC 14.2 / libstdc++ 14 / glibc 2.41, Debian trixie, aarch64, -O2 -ffp-contract=off).

//! Exact bit equality of the random module with the C++ oracle.

use std::sync::Mutex;

use akantu_core::random::distributions::*;
use akantu_core::random::{
    Distribution, IdxSlot, MinstdRand0, RandomDistributionType, RandomGenerator, RandomParameter,
    UIntSlot, generate_canonical,
};
use serde_json::Value;

/// Tests touching the process-global generators run one at a time.
static GLOBAL: Mutex<()> = Mutex::new(());

fn fixture(name: &str) -> Value {
    let path = format!(
        "{}/tests/fixtures/random/{name}",
        env!("CARGO_MANIFEST_DIR")
    );
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("{path}: {e}"))
}

fn hex(v: &Value) -> f64 {
    f64::from_bits(u64::from_str_radix(v.as_str().expect("hex string"), 16).expect("hex"))
}

fn hexes(v: &Value) -> Vec<u64> {
    v.as_array()
        .expect("array")
        .iter()
        .map(|x| u64::from_str_radix(x.as_str().expect("hex string"), 16).expect("hex"))
        .collect()
}

fn long(v: &Value) -> i64 {
    v.as_str().expect("seed string").parse().expect("seed")
}

fn bits(v: &[f64]) -> Vec<u64> {
    v.iter().map(|x| x.to_bits()).collect()
}

/// Compare and report the first mismatching index.
fn assert_bits(context: &str, got: &[u64], expected: &[u64]) {
    assert_eq!(got.len(), expected.len(), "{context}: length");
    if let Some(i) = (0..got.len()).find(|&i| got[i] != expected[i]) {
        panic!(
            "{context}: first mismatch at index {i}: got {:016x} ({:e}), expected {:016x} ({:e})",
            got[i],
            f64::from_bits(got[i]),
            expected[i],
            f64::from_bits(expected[i])
        );
    }
}

#[test]
fn fixtures_provenance() {
    for name in [
        "engine.json",
        "canonical.json",
        "distributions.json",
        "random_parameter.json",
    ] {
        let meta = &fixture(name)["meta"];
        // Either authoritative oracle platform (D-043, D-073): the x86-64-v3
        // regeneration reproduces every value of these fixtures bit for bit
        // (class X0); only the metadata names the platform.
        assert!(
            matches!(meta["arch"].as_str(), Some("aarch64" | "x86_64")),
            "{name}: {}",
            meta["arch"]
        );
        assert_eq!(meta["glibc"], "2.41", "{name}");
        assert_eq!(meta["glibcxx_release"], 14, "{name}");
        assert!(
            meta["flags"]
                .as_str()
                .unwrap()
                .contains("-ffp-contract=off"),
            "{name}"
        );
        assert_eq!(meta["sizeof_uint_fast32_t"], 8, "{name}");
    }
}

#[test]
fn engine_sequences() {
    let f = fixture("engine.json");
    assert_eq!(f["min"], 1);
    assert_eq!(f["max"], 2_147_483_646);
    assert_eq!(f["default_constructed_state"], MinstdRand0::new().state());
    let mut e = MinstdRand0::new();
    e.discard(9999);
    assert_eq!(f["default_10000th"], e.next_u32());

    let seeds = f["seeds"].as_array().unwrap();
    assert!(seeds.len() >= 20);
    for case in seeds {
        let seed = long(&case["seed"]);
        let mut e = MinstdRand0::with_seed_long(seed);
        assert_eq!(case["state"], e.state(), "seed {seed}: state after seeding");
        for (i, v) in case["values"].as_array().unwrap().iter().enumerate() {
            assert_eq!(*v, e.next_u32(), "seed {seed}: value {i}");
        }
    }
}

#[test]
fn canonical_sequences() {
    let f = fixture("canonical.json");
    for case in f["cases"].as_array().unwrap() {
        let seed = long(&case["seed"]);
        let mut e = MinstdRand0::with_seed_long(seed);
        let expected = hexes(&case["values"]);
        let got: Vec<f64> = (0..expected.len())
            .map(|_| generate_canonical(&mut e))
            .collect();
        assert_bits(&format!("canonical seed {seed}"), &bits(&got), &expected);
        assert_eq!(case["state_after"], e.state(), "canonical seed {seed}");
    }
}

/// Build a std distribution from the probe's name and parameters (std order).
fn std_distribution(name: &str, p: &[f64]) -> Distribution {
    match name {
        "uniform_real" => Distribution::Uniform(UniformRealDistribution::new(p[0], p[1])),
        "exponential" => Distribution::Exponential(ExponentialDistribution::new(p[0])),
        "gamma" => Distribution::Gamma(GammaDistribution::new(p[0], p[1])),
        "weibull" => Distribution::Weibull(WeibullDistribution::new(p[0], p[1])),
        "extreme_value" => Distribution::ExtremeValue(ExtremeValueDistribution::new(p[0], p[1])),
        "normal" => Distribution::Normal(NormalDistribution::new(p[0], p[1])),
        "lognormal" => Distribution::Lognormal(LognormalDistribution::new(p[0], p[1])),
        "chi_squared" => Distribution::ChiSquared(ChiSquaredDistribution::new(p[0])),
        "cauchy" => Distribution::Cauchy(CauchyDistribution::new(p[0], p[1])),
        "fisher_f" => Distribution::FisherF(FisherFDistribution::new(p[0], p[1])),
        "student_t" => Distribution::StudentT(StudentTDistribution::new(p[0])),
        other => panic!("unknown distribution {other}"),
    }
}

#[test]
fn distribution_sequences() {
    let f = fixture("distributions.json");
    let cases = f["cases"].as_array().unwrap();
    let mut seen = std::collections::BTreeSet::new();
    for case in cases {
        let name = case["dist"].as_str().unwrap();
        seen.insert(name.to_owned());
        let params: Vec<f64> = case["params"].as_array().unwrap().iter().map(hex).collect();
        let seed = long(&case["seed"]);
        let context = format!("{name}{params:?} seed {seed}");
        let mut d = std_distribution(name, &params);
        let mut e = MinstdRand0::with_seed_long(seed);
        let expected = hexes(&case["values"]);
        let got: Vec<f64> = (0..expected.len()).map(|_| d.sample(&mut e)).collect();
        assert_bits(&context, &bits(&got), &expected);
        assert_eq!(case["state_after"], e.state(), "{context}: engine calls");
        assert_eq!(case["printed"], d.params_string(), "{context}: operator<<");
    }
    assert_eq!(seen.len(), 11, "all eleven distributions covered");
}

fn make_from_case(case: &Value) -> RandomParameter {
    let ty: RandomDistributionType = case["type"].as_str().unwrap().parse().unwrap();
    let base = hex(&case["base"]);
    let (a, b) = (hex(&case["a"]), hex(&case["b"]));
    match case["nparams"].as_u64().unwrap() {
        0 => RandomParameter::from_parsed(base, ty, &[]),
        1 => RandomParameter::from_parsed(base, ty, &[a]),
        _ => RandomParameter::from_parsed(base, ty, &[a, b]),
    }
}

#[test]
fn make_random_parameter_chunks_explicit_engine() {
    let f = fixture("random_parameter.json");
    for case in f["make"].as_array().unwrap() {
        let mut p = make_from_case(case);
        let context = format!("make {}", case["printed_initial"]);
        assert_eq!(case["printed_initial"], p.to_string(), "{context}");
        // The probe seeds RandomGenerator<Idx> with 1 before each case.
        let mut e = MinstdRand0::with_seed_long(1);
        for (k, chunk) in case["chunks"].as_array().unwrap().iter().enumerate() {
            let expected = hexes(&chunk["values"]);
            let mut got = vec![0.0; expected.len()];
            p.set_values_with(&mut e, &mut got);
            assert_bits(&format!("{context} chunk {k}"), &bits(&got), &expected);
            assert_eq!(chunk["state"], e.state(), "{context} chunk {k}");
            assert_eq!(chunk["printed"], p.to_string(), "{context} chunk {k}");
        }
    }
}

#[test]
fn make_random_parameter_chunks_global_engine() {
    let _guard = GLOBAL
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let f = fixture("random_parameter.json");
    for case in f["make"].as_array().unwrap() {
        let mut p = make_from_case(case);
        RandomGenerator::<IdxSlot>::seed(1);
        for chunk in case["chunks"].as_array().unwrap() {
            let expected = hexes(&chunk["values"]);
            let mut got = vec![0.0; expected.len()];
            p.set_values(&mut got);
            assert_bits("global", &bits(&got), &expected);
            assert_eq!(
                chunk["state"],
                RandomGenerator::<IdxSlot>::engine_snapshot().state()
            );
        }
    }
}

#[test]
fn interleaving_and_copy_semantics() {
    let f = fixture("random_parameter.json");
    let events = f["interleave"].as_array().unwrap();
    let mut e = MinstdRand0::with_seed_long(2024);
    let mut pn = RandomParameter::make(10.0, RandomDistributionType::Normal, 0.0, 1.0);
    let mut pg = RandomParameter::make(0.0, RandomDistributionType::Gamma, 0.7, 2.0);
    let mut pu = RandomParameter::new(3.0);
    let mut pl = RandomParameter::make(0.0, RandomDistributionType::Lognormal, 0.0, 0.3);
    let mut pn_copy = None;
    let mut pl_copy = None;
    let mut idx = 0;
    let mut check = |name: &str, p: &mut RandomParameter, e: &mut MinstdRand0| {
        let ev = &events[idx];
        idx += 1;
        assert_eq!(ev["param"], name, "event {idx}");
        let expected = hexes(&ev["values"]);
        let mut got = vec![0.0; expected.len()];
        p.set_values_with(e, &mut got);
        assert_bits(&format!("event {idx} ({name})"), &bits(&got), &expected);
        assert_eq!(ev["state"], e.state(), "event {idx} ({name})");
        assert_eq!(ev["printed"], p.to_string(), "event {idx} ({name})");
    };
    // Same script as dump_random.cc.
    check("n", &mut pn, &mut e);
    check("g", &mut pg, &mut e);
    check("u", &mut pu, &mut e);
    let c = pn_copy.insert(pn.clone()); // copy constructor: cached value copied
    check("n", &mut pn, &mut e);
    check("n_copy", c, &mut e);
    check("l", &mut pl, &mut e);
    let c = pl_copy.insert(pl.clone());
    check("l_copy", c, &mut e);
    check("l", &mut pl, &mut e);
    pn = pg.clone(); // copy assignment
    check("n", &mut pn, &mut e);
    check("g", &mut pg, &mut e);
    check("u", &mut pu, &mut e);
    assert_eq!(idx, events.len());
}

#[test]
fn printing_of_base_values_and_parameters() {
    let f = fixture("random_parameter.json");
    for case in f["print_base"].as_array().unwrap() {
        let x = hex(&case["x"]);
        let s = RandomParameter::new(x).to_string();
        let expected = format!(
            "{} + uniform [ 0.00000000000000000e+00 0.00000000000000000e+00 ]",
            case["s"].as_str().unwrap()
        );
        assert_eq!(s, expected, "base {x:e}");
    }
    for case in f["print_sci"].as_array().unwrap() {
        let x = hex(&case["x"]);
        let d = Distribution::Exponential(ExponentialDistribution::new(x));
        assert_eq!(case["s"], d.params_string(), "scientific {x:e}");
    }
}

#[test]
fn global_generators_are_independent() {
    let _guard = GLOBAL
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let f = fixture("random_parameter.json");
    // RandomGenerator<UInt> is never seeded: its first values are those of 5489.
    let mut e = MinstdRand0::with_seed_long(5489);
    for v in f["uint_generator_first5"].as_array().unwrap() {
        assert_eq!(*v, e.next_u32());
    }
    let mut u = RandomGenerator::<UIntSlot>::new();
    assert_eq!(RandomGenerator::<UIntSlot>::get_seed(), 5489);
    RandomGenerator::<IdxSlot>::seed(77);
    let mut i = RandomGenerator::<IdxSlot>::new();
    let mut fresh = MinstdRand0::with_seed_long(5489);
    for v in f["idx_seed77_first5"].as_array().unwrap() {
        assert_eq!(u.next_u32(), fresh.next_u32());
        assert_eq!(*v, i.next_u32());
    }
    assert_eq!(f["idx_seed"], RandomGenerator::<IdxSlot>::get_seed());
    assert_eq!(f["uint_seed"], RandomGenerator::<UIntSlot>::get_seed());
    assert_eq!(
        RandomGenerator::<IdxSlot>::describe(),
        "RandGenerator [seed=77]"
    );
}
